insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('07c54d12-212d-495c-905c-44953a331332', 'zh', 'hey-mama-challenge', 'Hey Mama挑战', 'Mnet《街舞女战士》队长任务编舞在2021年演变为席卷全球的TikTok挑战', '2021年8月至10月播出的Mnet《街舞女战士》队长任务环节中,Waveya舞团舞者Noze为大卫·库塔(David Guetta)的歌曲《Hey Mama》编排并展示了舞蹈。这段编舞随后在TikTok上扩散开来,连K-pop偶像和海外舞者都纷纷加入,形成了"Hey Mama挑战",成为2021年下半年最具代表性的短视频内容之一。', 'Mnet《街舞女战士》队长任务环节,舞者Noze编舞(2021年播出)', '适合在谈论舞者充满张力的表演,或生存类综艺热潮时使用', NULL, array['SWF Hey Mama', 'Noze Hey Mama', '헤이마마 챌린지']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('1a9749b5-f672-4357-9ffb-37b2a06696b2', 'zh', 'very-demure-very-mindful', 'Very Demure, Very Mindful(端庄又体贴)', '网红朱尔斯·勒布朗(Jools Lebron)带火的流行语,形容不张扬、举止得体的态度', '网红朱尔斯·勒布朗在讲解职场礼仪时反复使用的口头禅"非常端庄,非常体贴(very demure, very mindful)"直接演变成了网络热梗,常被用来以夸张语气称赞克制得体的行为。在韩国,这句话也以"데뮤어하다(demure)"的翻译形式流行开来。', '2024年8月,TikTok博主朱尔斯·勒布朗(@joolieannie)发布的视频引爆话题,并迅速传遍全球。', '用夸张的语气假装端庄得体时使用的说法', NULL, array['Very Demure, Very Mindful', '端庄又体贴梗', '베리 데뮤어 베리 마인드풀']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('2da1eea1-792f-4aec-aa4c-4bbbd938c911', 'zh', 'top-blade-spinning-top-boom', '战斗陀螺(Top Blade)热潮', '2001至2002年席卷韩国的陀螺玩具热潮', '2001年10月SBS开始播出动画《战斗陀螺》,由此在韩国掀起了陀螺玩具热潮。玩具制造商Sonokong凭借相关产品创下近1万亿韩元的销售额,但热潮之下也出现了中国产仿冒陀螺泛滥的社会问题。', '《战斗陀螺》是一部以陀螺玩具为题材的日本动画,在韩国于2001年10月9日至2002年4月9日期间由SBS播出。随着动画播出,韩国国内也掀起陀螺热潮,玩具企业Sonokong凭借相关商品创下近1万亿韩元的销售额,仅2001年一年销量就超过3000万个。热度爆发的同时,中国产仿冒品在市场上泛滥,演变成社会问题,SBS综艺节目《好奇心天国》甚至专门报道过此现象。此后该系列延续至V、G季,三年间共播出154集。', '可作为2000年代初儿童玩具热潮的代表案例来提及', NULL, array['战斗陀螺', '爆旋陀螺', '탑블레이드 팽이 붐']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
