values
  ('33a07b6f-3e18-4d8a-8e95-7be28cd11f50', 'zh', 'feel-the-rhythm-of-korea-tiger-descends', '老虎下山来(범 내려온다)', '韩国旅游发展局宣传片中乐队LEENALCHI的歌曲与Ambiguous Dance Company的沙雕舞蹈结合,引发全球热议的视频', '韩国旅游发展局于2020年7月30日发布的海外宣传企划"Feel the rhythm of Korea"系列中的首尔篇,特点是Ambiguous Dance Company舞团随着乐队LEENALCHI演唱的盘索里风格歌曲《老虎下山来》,以一本正经的表情跳着诡异舞蹈。该视频在YouTube上播放量突破3亿次,引发全球热议,并在西班牙举办的旅游创新奖上获奖。', '韩国旅游发展局海外宣传企划"Feel the rhythm of Korea"首尔篇(2020年7月30日发布)', '适合在谈论一本正经跳沙雕舞或"国货自豪"类内容时使用', NULL, array['Feel the rhythm of Korea', 'LEENALCHI老虎下山来', '범 내려온다']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
