  ('3e691e5f-5688-4052-9449-ca1ca3c7dce6', 'zh', 'holy-war-kang-min-vs-ma-jae-yoon', '圣战(성전)', '星际争霸贴吧为姜民对马在允的对决所起的称号', '在神族对战虫族普遍处于劣势的时期,姜民被视为唯一能与虫族最强者马在允抗衡的选手,星际争霸论坛因此将两人的对决称为"圣战"。这场比赛被视为关乎种族尊严的特殊对决。这一说法在2006年前后马在允全盛期广为流传。', '星际争霸论坛用语,指马在允全盛期(2006年前后)与姜民的对决', '用于指代关乎种族(阵营)尊严的宿敌对决', NULL, array['姜民马在允圣战', '성전']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
