values
  ('6ae6b4c5-694b-4bf3-a1d8-08263fabcee4', 'zh', 'bts-dynamite-challenge', 'BTS《Dynamite》挑战', '防弹少年团2020年首支全英文单曲《Dynamite》重点编舞的TikTok挑战', '防弹少年团于2020年8月21日发布的首支全英文单曲《Dynamite》,以副歌部分的甩头动作以及致敬迈克尔·杰克逊《Billie Jean》的踩步为特色。歌曲发布后,以话题标签"#DynamiteChallenge"掀起的TikTok翻跳挑战风靡全球。', '防弹少年团单曲《Dynamite》(2020年8月21日发布)编舞', '适合在谈论2020年代表性全球舞蹈挑战时使用', NULL, array['Dynamite舞蹈挑战', '다이너마이트 챌린지']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
