values
  ('73e23497-f290-4a59-9ecb-78ec91f1a4c4', 'zh', 'cupid-challenge', 'Cupid挑战', 'FIFTY FIFTY《Cupid》Twin版歌曲带动的2023年全球第一舞蹈挑战', '女团FIFTY FIFTY的《Cupid》Twin版经加速处理后成为TikTok热门背景音乐,在全球催生出数千条舞蹈挑战视频。该曲创下连续25周进入Billboard Hot 100的K-pop女团最长纪录,并被评为2023年TikTok"The Playlist"全球热门歌曲第一名。', 'FIFTY FIFTY(ATTRAKT)2023年发行歌曲,因TikTok加速版扩散而演变为挑战', '可用于回顾K-pop舞蹈挑战或翻跳内容', '此后因成员与经纪公司纠纷,组合活动实际上陷入停摆,提及时需注意话题敏感性', array['Cupid挑战', 'FIFTY FIFTY Cupid', '큐피드 챌린지']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
