values
  ('7f167258-8c77-4baf-bf90-6075765e36c7', 'zh', 'decide-to-appear-in-algorithm', '决定要刷到对方的算法推荐', '为了让暗恋对象在社交媒体算法中刷到自己而跳的中国风舞蹈挑战', '该舞蹈源自中国抖音上流行的动画插曲《谁敢想》,后被改编为韩式版本。参与者会写下"因为某某不回消息,所以决定要出现在(对方的)算法推荐里"这类恳切的告白文字,并配合跳舞,寓意希望借此登上对方的社交媒体推荐页面,该形式也被许多政府机关宣传视频广泛采用。', '中国抖音流行的动画插曲《谁敢想》舞蹈挑战,与韩式告白文字结合后演变而成', '可用于想向暗恋对象或特定对象刷存在感的宣传视频等场景', NULL, array['谁敢想挑战', '算法挑战', '알고리즘에 나타나기로 마음먹음']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
