values
  ('82257be7-698f-4d1d-9926-94c55132b85c', 'zh', 'kim-do-yeong-thanks-to-you-meme', '金道英"全靠你才撑得住"应援语梗', 'KIA球迷为金道英打气的应援标语梗,后来甚至真的带动了他的打击手感回升', '2024年KBO联赛中,KIA老虎队金道英的一名球迷制作了"道英啊,全靠你(粉丝)才撑得住"(全罗道方言)这句应援标语,被转播镜头拍到后成为热门梗。之后金道英举起写有这句话的画板并以此更换个人资料照片,随后打击状态明显回升的后续故事更是让这个梗持续升温。', '2024年KIA老虎队比赛转播中,球迷应援标语被镜头捕捉后开始扩散', '用于表达爱意、加油打气的语境', NULL, array['全靠你才撑得住', '도영이는 니땀시 살어야', '김도영 니 땀시 살어야']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('90c32145-5e91-4bb0-a9de-4cc3dfac13e3', 'zh', 'lim-yo-hwan-terran-emperor', '林拓焕"人族皇帝"(임요환)', '星际争霸职业选手林拓焕的绰号,2001年诞生的电竞明星', '以ID"SlayerS_BoxeR"活跃的林拓焕,凭借当时被认为最弱种族的人族在2001、2002年连续两届WCG夺冠,由此获得"人族皇帝"的绰号。他是韩国电竞早期的顶级明星,曾引发大众级别的追星热潮。', '源自星际争霸职业选手林拓焕的比赛战绩与粉丝群体所赋予的绰号', '用于电竞早期历史或星际争霸回顾类内容', NULL, array['皇帝', 'BoxeR', '임요환']::text[], '[{"text": "这选手完全是林拓焕人族皇帝级别的气场", "situation": "聊天软件"}, {"text": "说到电竞历史就得从林拓焕说起", "situation": "社交媒体评论"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
  (meme_id, locale, localized_slug, title, summary, description, origin, usage_note, caution, aliases, usage_examples, status, source_updated_at, provider, model, prompt_version, translated_at, reviewed_at, reviewed_by)
values
  ('a98a4c75-0b3b-43cf-9901-a04d855211e7', 'zh', 'mashimaro', '麻薯兔(마시마로)', '2000年登场、以坏笑表情引领"猎奇"热潮的兔子Flash动画角色', '麻薯兔是金载仁制作的7集系列Flash动画《麻薯兔森林物语》的主角,以不走可爱路线、带着坏心眼表情和无厘头行为打破了以往角色形象的常规套路。它通过网络爆发式传播,并在2001年正式推出角色周边商品。', '金载仁构思的角色最初被公司拒绝,他随后通过网络漫画网站"Enfo"自行发布,由此走红。', '常作为2000年代初网络文化及"猎奇"风潮的代表案例被提及', '对现在的年轻一代来说可能比较陌生,提及时需要加以说明', array['猎奇兔子', '麻薯兔森林物语', '마시마로']::text[], '[{"text": "这家伙的表情完全是麻薯兔st的坏笑ㅋㅋ", "situation": "聊天软件"}, {"text": "这个角色麻薯兔级别的沙雕啊", "situation": "社交媒体评论"}]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
