values
  ('b131ee97-8ec6-4646-8252-5783f86571f9', 'zh', 'triple-bunker-rush', '三连堡(삼연벙)', '林拓焕对洪辰浩连续三次成功偷营(Bunker Rush)的传奇比赛', '指2004年11月12日EVER星际联赛2004四强第2周中,林拓焕对阵洪辰浩时连续三次成功实施"偷兵营(Bunker Rush)"战术的比赛与策略。他在对方阵地建造兵营从而提前结束比赛的战术竟然连续得手三次,轰动一时。此后该词含义延伸,也被用来泛指某种行为或状况连续发生三次的情形。', '2004年11月12日EVER星际联赛2004四强,林拓焕对阵洪辰浩之战', '用于同一情况或行为连续发生三次时', NULL, array['三连Bunker', '삼연벙']::text[], '[]'::jsonb, 'machine', '2026-07-15T15:30:00.191373+00:00', 'claude', 'claude-fable-5', 12, now(), null, null)
insert into public.meme_translations
